"""Build a standalone interactive tracker from the research backlog."""
import json
import re
from pathlib import Path

root = Path(__file__).resolve().parents[2]
source = (root / 'docs/PROJECT_BACKLOG.md').read_text(encoding='utf-8')
phases = []
for line in source.splitlines():
    if re.match(r'## P\d —', line):
        phases.append({'title': line[3:], 'tasks': [], 'description': ''})
    match = re.match(r'- \[([ x])\] (P\d+\.\d+) (.*)', line)
    if match:
        phases[-1]['tasks'].append({'id': match[2], 'text': match[3], 'done': match[1] == 'x'})
    if line.startswith('Deliverable:') and phases:
        phases[-1]['description'] = line
template = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>HEMS · Research backlog</title>
<style>
:root{font-family:Inter,Segoe UI,Arial,sans-serif;color:#18332e;background:#f3f5f0;accent-color:#18755e}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button,select{cursor:pointer}button,.button{background:white;color:#18332e;border:1px solid #ccd6cf;border-radius:8px;padding:9px 13px;text-decoration:none;font-size:13px}button:hover,.button:hover{background:#edf5ed}a{color:#17674e}header{background:#153e34;color:#fff;padding:38px max(24px,calc((100vw - 1160px)/2));}header small{letter-spacing:3px;color:#a8d5bc;font-weight:700}h1{font-size:clamp(30px,4vw,46px);letter-spacing:-1.5px;margin:12px 0}header p{color:#c9ded5;max-width:760px;line-height:1.6}main{max-width:1208px;margin:auto;padding:24px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stat{background:#fff;border:1px solid #dce3da;padding:20px;border-radius:12px}.stat strong{display:block;font-size:30px;margin-bottom:4px}.stat span{color:#61746a;font-size:14px}.bar{height:6px;background:#e1e9df;border-radius:9px;overflow:hidden;margin-top:14px}.bar i{height:100%;display:block;background:#2b8769;transition:width .2s}.next{margin:20px 0;background:#e5eddb;border:1px solid #cbd9ba;padding:20px;border-radius:12px}.next h2{font-size:18px;margin:0 0 8px}.next p{margin:0;line-height:1.6;color:#4c604d}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0 16px;align-items:center}.toolbar input{flex:1;min-width:190px;padding:11px;border:1px solid #ccd6cf;border-radius:8px;background:white}.toolbar select{padding:10px;border:1px solid #ccd6cf;border-radius:8px;background:white}.phase{background:white;border:1px solid #d9e1d6;border-radius:12px;margin-bottom:14px;overflow:hidden}.phase>summary{padding:20px;cursor:pointer;font-weight:650;display:flex;align-items:center;gap:14px;list-style:none}.phase>summary::before{content:'›';font-size:24px;color:#58816b}.phase[open]>summary::before{transform:rotate(90deg)}.phase>summary span:first-of-type{flex:1}.count{font-size:12px;color:#54705f;background:#eff4eb;padding:6px 10px;border-radius:20px;white-space:nowrap}.description{padding:0 22px 15px;color:#65766a;font-size:13px;line-height:1.5}.task{border-top:1px solid #edf0e9;padding:16px 22px;display:grid;grid-template-columns:22px 1fr;gap:12px}.task input[type=checkbox]{width:19px;height:19px;margin:2px 0;cursor:pointer}.task label{cursor:pointer;line-height:1.5;font-size:14px;display:block}.task label b{font-size:12px;color:#36715c;margin-right:8px;white-space:nowrap}.task.done label{color:#728075}.task.done label .text{text-decoration:line-through}.task details{margin-top:8px;font-size:12px;color:#687c6c}.task details summary{cursor:pointer}.task textarea{width:100%;margin-top:8px;min-height:65px;border:1px solid #d4ded1;border-radius:6px;padding:10px;resize:vertical;font-size:13px}.meta{font-size:11px;margin-top:7px;color:#70806e}.footer{color:#6b796c;font-size:12px;line-height:1.8;padding:15px 0 30px}.actions{display:flex;gap:8px;flex-wrap:wrap}.empty{padding:35px;text-align:center;color:#667b6d}#notice{font-size:12px;margin-top:10px;color:#51735c}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #dcad46;outline-offset:3px}@media(max-width:600px){main{padding:16px}.stats{gap:8px}.stat{padding:14px}.stat strong{font-size:24px}.phase>summary{padding:15px}.task{padding:14px}.count{font-size:11px}header{padding:28px 20px}}
</style>
<header><small>ARTICLE / RESEARCH WORKSPACE</small><h1>One task closer.</h1><p>Causal diagnosis & safe adaptive intervention planning for preference-aware home energy management. Your implementation roadmap, from simulation to publication.</p></header>
<main><section class="stats" aria-label="Project progress"><div class="stat"><strong id="complete">3</strong><span>Tasks completed</span></div><div class="stat"><strong id="remaining">—</strong><span>Tasks remaining</span></div><div class="stat"><strong id="percentage">—</strong><span>Overall completion</span><div class="bar"><i id="progress"></i></div></div></section>
<section class="next"><h2>Current focus · P0 — Research specification</h2><p>Review implementation literature and consolidate agreed research decisions, starting with P0.1. P1.4 equipment-sizing verification follows the specification review. <a href="P0_IMPLEMENTATION_LITERATURE.md">Open the implementation literature map</a>.</p></section>
<div class="toolbar"><input id="search" type="search" aria-label="Search tasks" placeholder="Search tasks or IDs…"><select id="filter" aria-label="Filter by completion"><option value="all">All tasks</option><option value="pending">Pending</option><option value="done">Completed</option></select><button id="expand">Expand all</button><button id="collapse">Collapse all</button></div>
<div id="phases"></div><p id="results" aria-live="polite"></p>
<div class="actions"><button id="export">Export progress</button><button id="import">Import progress</button><a class="button" href="PROJECT_BACKLOG.md">Markdown source</a><a class="button" href="../reports/setup_validation.md">Setup evidence</a><button id="reset">Reset to verified baseline</button><input id="file" type="file" accept="application/json,.json" hidden></div>
<div id="notice" role="status"></div><div class="footer"><b>Completion means evidence.</b> Check a task when its scoped work and relevant validation are complete; record results in its notes. Initial checks reflect saved P1.1–P1.3 validation, not a new run. Unchecked tasks may contain partial work.<br>Progress and notes are saved in this browser only. Export a backup to move between browsers or preserve your records. This page does not automatically update the Markdown file. Scope and unresolved scientific decisions remain subject to your instructions.</div></main>
<script>
const phases=__DATA__;
const tasks=phases.flatMap(p=>p.tasks), key='hems-research-backlog-v1';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baseline=()=>Object.fromEntries(tasks.map(t=>[t.id,{done:t.done,note:'',updated:''}]));
let state=baseline(), opened=new Set(phases.map(p=>p.title));
function valid(data){if(!data||data.version!==1||!data.tasks||typeof data.tasks!=='object')throw Error('Invalid backup format.');const out=baseline();for(const t of tasks){const x=data.tasks[t.id];if(!x||typeof x.done!=='boolean'||typeof x.note!=='string'||typeof x.updated!=='string')throw Error('Backup is missing valid task records.');out[t.id]={done:x.done,note:x.note,updated:x.updated};}return out;}
try{const saved=localStorage.getItem(key);if(saved)state=valid(JSON.parse(saved));}catch(e){$('notice').textContent='Saved progress could not be loaded. Verified baseline shown; export a backup before closing.';}
function save(){try{localStorage.setItem(key,JSON.stringify({version:1,tasks:state}));$('notice').textContent='Progress saved in this browser.';}catch(e){$('notice').textContent='Browser storage is unavailable. Export your progress before closing.';}}
function stats(){const n=tasks.filter(t=>state[t.id].done).length,p=Math.round(n/tasks.length*100);$('complete').textContent=n+' / '+tasks.length;$('remaining').textContent=tasks.length-n;$('percentage').textContent=p+'%';$('progress').style.width=p+'%';}
function render(){stats();const query=$('search').value.toLowerCase().trim(),filter=$('filter').value;let shown=0;$('phases').innerHTML=phases.map(p=>{const list=p.tasks.filter(t=>(t.id+' '+t.text+' '+p.title).toLowerCase().includes(query)&&(filter==='all'||state[t.id].done===(filter==='done')));if(!list.length)return '';shown+=list.length;const n=p.tasks.filter(t=>state[t.id].done).length;return `<details class="phase" data-phase="${esc(p.title)}" ${opened.has(p.title)?'open':''}><summary><span>${esc(p.title)}</span><span class="count">${n} / ${p.tasks.length}</span></summary><div class="description">${esc(p.description)}</div>${list.map(t=>{const s=state[t.id];return `<div class="task ${s.done?'done':''}"><input type="checkbox" id="${t.id}" data-task="${t.id}" ${s.done?'checked':''}><div><label for="${t.id}"><b>${t.id}</b><span class="text">${esc(t.text)}</span></label><details><summary>Notes & evidence${s.note?' · saved':''}</summary><textarea data-note="${t.id}" aria-label="Notes and evidence for ${t.id}" placeholder="Evidence path, validation results, decisions, or blockers…">${esc(s.note)}</textarea></details>${s.updated?`<div class="meta">Updated ${esc(new Date(s.updated).toLocaleString())}</div>`:''}</div></div>`;}).join('')}</details>`;}).join('')||'<div class="empty">No matching tasks. Try another search or filter.</div>';$('results').textContent=shown+' tasks shown';document.querySelectorAll('.phase').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)opened.add(el.dataset.phase);else opened.delete(el.dataset.phase);}));}
$('phases').addEventListener('change',e=>{const id=e.target.dataset.task;if(id){state[id].done=e.target.checked;state[id].updated=new Date().toISOString();save();render();document.getElementById(id)?.focus();}});
$('phases').addEventListener('input',e=>{const id=e.target.dataset.note;if(id){state[id].note=e.target.value;state[id].updated=new Date().toISOString();save();}});
$('search').addEventListener('input',render);$('filter').addEventListener('change',render);
$('expand').onclick=()=>{opened=new Set(phases.map(p=>p.title));render();};$('collapse').onclick=()=>{opened.clear();render();};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),tasks:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hems-backlog-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('notice').textContent='Progress backup exported.';};
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const next=valid(JSON.parse(await file.text()));if(confirm('Replace current progress and notes with this backup?')){state=next;save();render();}}catch(error){$('notice').textContent='Import failed: '+error.message;}e.target.value='';};
$('reset').onclick=()=>{if(confirm('Reset every checkbox to the verified baseline and erase all notes? Export a backup first if needed.')){state=baseline();save();render();}};
render();
</script></html>'''
output = root / 'docs/PROJECT_BACKLOG.html'
output.write_text(template.replace('__DATA__', json.dumps(phases, ensure_ascii=False).replace('<', '\\u003c')), encoding='utf-8')
print(f'Built {output}: {len(phases)} phases, {sum(len(p["tasks"]) for p in phases)} tasks')
